    discoveryConsentTitle:["Discover your investment preferences","Découvre tes préférences d’investissement"], discoveryConsentHelp:["Explore 30 investment scenarios to understand your preferences. The questionnaire is indicative. Your choices and optional confidence remain in the local save. Unsure, skip, and undo are available; participation is optional.","Explore 30 situations de placement pour comprendre tes préférences. Le questionnaire est indicatif. Tes réponses et ta confiance facultative restent dans la sauvegarde locale. Tu peux hésiter, passer et annuler ; la participation est facultative."], discoveryConsent:["I agree to complete the questionnaire.","J’accepte de répondre au questionnaire."], beginDiscovery:["Begin Discovery →","Commencer Discovery →"], discoveryConsentRequired:["Confirm consent to start the simulation.","Confirme ton consentement pour commencer la simulation."], discoveryQuestion:["Answer Yes to switch, or No to keep your current choice.","Réponds Oui pour changer, ou Non pour garder ton choix actuel."], discoveryProgress:["Discovery progress","Progression du questionnaire"], discoveryStatement:["Imagine your current option is to {b}. Would you switch and {a}?","Pour l’instant, tu peux {b}. Tu veux plutôt {a} ?"], discoveryWealthContext:["Starting balance {wealth}","Solde de départ de {wealth}"], discoveryPathStatement:["Both investments start at 100. Your current investment is worth {b}. Would you switch to the one worth {a}?","Les deux placements partent de 100. Ton placement actuel vaut {b}. Veux-tu passer à celui qui vaut {a} ?"], discoveryPathContext:["Both placements have the same fees and give each final value a 50% chance.","Les deux placements ont les mêmes frais. Chaque valeur finale a une chance sur deux de se réaliser."], discoveryComprehensionStatement:["Imagine an event has a 1% chance each time. In 100 trials, your current answer is to {b}. Would you switch and {a}?","Un événement a 1 % de chances de se produire à chaque essai. Sur 100 essais, ta réponse actuelle est de {b}. Préfères-tu {a} ?"], discoveryUnderstanding:["Probability check","Vérification des probabilités"], discoveryUnderstood:["Correct","Correcte"], discoveryToReview:["Review the question","À revoir"], chooseA:["♥ Yes, switch","♥ Oui, je change"], chooseB:["✕ No, keep it","✕ Non, je garde"], referenceWealth:["Starting balance","Capital de départ"], confidenceOptional:["Confidence in your answers (optional, 1–5)","Confiance dans tes réponses (facultatif, 1–5)"], scoreMethod:["Prudence index = round(1 + 29 × fraction of prudent choices) among 20 scored items. At least 70% resolved responses are required; missing responses produce an extreme-case sensitivity range.","Indice de prudence = arrondi(1 + 29 × proportion de réponses prudentes) parmi 20 items notés. Au moins 70 % de réponses tranchées sont nécessaires ; les réponses manquantes donnent une plage de sensibilité extrême."], discoverySeparate:["These results do not change your financial loss budget, estimate utility parameters or diagnose a bias. Conditional preferences are not a validated psychological scale.","Ces résultats ne modifient pas ton budget de perte financière, n’estiment pas les paramètres d’utilité et ne diagnostiquent aucun biais. Les préférences conditionnelles ne sont pas une échelle psychologique validée."], mixed_loss_choices:["Mixed gains and losses","Gains et pertes possibles"], gain_risk:["Risk with gains","Risque face aux gains"], loss_risk:["Risk with losses","Risque face aux pertes"], rare_gain:["Rare gains","Gains rares"], rare_loss:["Rare losses","Pertes rares"], trajectory_tolerance:["Temporary declines","Baisses temporaires"], mixed_loss_choices_explain:["Share keeping the starting balance","Part des choix qui gardent le solde de départ"], gain_risk_explain:["Share choosing the guaranteed gain","Part des choix en faveur du gain garanti"], loss_risk_explain:["Share choosing the certain loss","Part des choix en faveur de la perte certaine"], rare_gain_explain:["Share choosing the guaranteed gain","Part des choix en faveur du gain garanti"], rare_loss_explain:["Share choosing the certain loss","Part des choix en faveur de la perte certaine"], trajectory_tolerance_explain:["Share choosing the shallower temporary decline","Part des choix en faveur du creux le plus faible"], unknown_card:["Unknown card in this session.","Carte inconnue dans cette session."], invalid_seed:["Invalid session seed.","Graine de session invalide."], invalid_currency:["Unsupported session currency.","Devise de session non prise en charge."], invalid_confidence:["Confidence must be between 1 and 5.","La confiance doit être comprise entre 1 et 5."], invalid_locale:["Invalid response language.","Langue de réponse invalide."],
    withdrawDiscovery:["Withdraw / reset Discovery","Retirer / réinitialiser Discovery"], withdrawDiscoveryConfirm:["Clear this save's Discovery answers and consent? Your financial mandate stays unchanged.","Effacer les réponses Discovery et le consentement de cette sauvegarde ? Le mandat financier reste inchangé."],
    fieldInfo:["Field explanation","Explication du champ"], fieldOptional:["(optional)","(facultatif)"],
